/**
 * Checks whether a customer has an active or completed data deletion request.
 */
export async function isCustomerErased(merchantId: string, customerId: string): Promise<boolean> {
  const result = await pool.query(
    `SELECT 1 FROM customers.erasure_requests
     WHERE merchant_id=$1 AND customer_id=$2 AND status IN ('pending', 'processing', 'completed')`,
    [merchantId, customerId],
  );
  return Boolean(result.rowCount);
}
