{"command":"create","path":"/workspace/source/apps/customer-service/src/erasure-service.ts","file_text":"import { createHash, randomUUID } from 'node:crypto';
import { Redis } from 'ioredis';
import type pg from 'pg';
import { config } from '../../../packages/config/src/index.js';
import { EVENT_TYPES } from '../../../packages/contracts/src/events.js';
import { pool, transaction } from '../../../packages/database/src/pool.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import { deleteMailpitMessagesForRecipient } from '../../../packages/notifications/src/mailpit.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, ensureBucket, objectStore } from '../../../packages/storage/src/minio.js';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  idempotency_key: string | null;
  status: 'pending' | 'processing' | 'failed' | 'completed';
  attempts: number;
  last_error: string | null;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

export interface ErasureRequestDto {
  id: string;
  customerId: string;
  status: 'pending' | 'processing' | 'failed' | 'completed';
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

function formatDto(row: ErasureRequestRow): ErasureRequestDto {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error,
  };
}

export class ErasureService {
  private redis: Redis | null = null;

  private getRedis(): Redis {
    if (!this.redis) {
      this.redis = new Redis(config().REDIS_URL);
    }
    return this.redis;
  }

  async create(merchantId: string, customerId: string, idempotencyKey: string): Promise<{ status: number; body: ErasureRequestDto }> {
    const requestPayload = { customerId };
    const hash = createHash('sha256').update(JSON.stringify(requestPayload)).digest('hex');

    const result = await transaction(async (client) => {
      // 1. Check idempotency keys table
      const insertedKey = await client.query(
        `INSERT INTO operations.idempotency_keys(merchant_id,scope,key,request_hash,expires_at)
         VALUES($1,'erasure-request',$2,$3,now()+interval '24 hours') ON CONFLICT DO NOTHING`,
        [merchantId, idempotencyKey, hash],
      );

      if (!insertedKey.rowCount) {
        // Idempotency key exists
        const existingKey = await client.query<{ request_hash: string; response_status: number | null; response_body: ErasureRequestDto | null }>(
          `SELECT request_hash,response_status,response_body FROM operations.idempotency_keys
           WHERE merchant_id=$1 AND scope='erasure-request' AND key=$2 FOR UPDATE`,
          [merchantId, idempotencyKey],
        );
        const keyRow = existingKey.rows[0];
        if (keyRow) {
          if (keyRow.request_hash !== hash) {
            throw Object.assign(new Error('idempotency key reused for a different customer'), { statusCode: 409 });
          }
          if (keyRow.response_body) {
            // Re-fetch latest state from DB
            const latest = await client.query<ErasureRequestRow>(
              `SELECT * FROM customers.erasure_requests WHERE id=$1 AND merchant_id=$2`,
              [keyRow.response_body.id, merchantId],
            );
            if (latest.rows[0]) {
              return { status: 202, body: formatDto(latest.rows[0]), trigger: latest.rows[0].status === 'failed' };
            }
            return { status: 202, body: keyRow.response_body, trigger: false };
          }
        }
      }

      // 2. Check if customer already has an erasure request
      const existingRequest = await client.query<ErasureRequestRow>(
        `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
        [merchantId, customerId],
      );

      if (existingRequest.rows[0]) {
        const dto = formatDto(existingRequest.rows[0]);
        await client.query(
          `UPDATE operations.idempotency_keys SET response_status=202,response_body=$4
           WHERE merchant_id=$1 AND scope='erasure-request' AND key=$2`,
          [merchantId, idempotencyKey, dto],
        );
        const shouldRetry = existingRequest.rows[0].status === 'failed';
        if (shouldRetry) {
          await client.query(
            `UPDATE customers.erasure_requests SET status='pending',updated_at=now()
             WHERE id=$1`,
            [existingRequest.rows[0].id],
          );
          await client.query(
            `INSERT INTO operations.jobs(queue,job_type,merchant_id,payload)
             VALUES('privacy','customer_erasure',$1,$2)`,
            [merchantId, { requestId: existingRequest.rows[0].id, customerId }],
          );
        }
        return { status: 202, body: dto, trigger: shouldRetry, requestId: existingRequest.rows[0].id };
      }

      // 3. Check if customer exists in customers.customers
      const customer = await client.query<{ id: string }>(
        `SELECT id FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
        [merchantId, customerId],
      );

      if (!customer.rowCount) {
        throw Object.assign(new Error('customer not found'), { statusCode: 404 });
      }

      // 4. Create new erasure request
      const created = await client.query<ErasureRequestRow>(
        `INSERT INTO customers.erasure_requests(merchant_id,customer_id,idempotency_key,status,attempts)
         VALUES($1,$2,$3,'pending',0) RETURNING *`,
        [merchantId, customerId, idempotencyKey],
      );

      const requestRow = created.rows[0]!;
      const dto = formatDto(requestRow);

      await client.query(
        `UPDATE operations.idempotency_keys SET response_status=202,response_body=$4
         WHERE merchant_id=$1 AND scope='erasure-request' AND key=$2`,
        [merchantId, idempotencyKey, dto],
      );

      await client.query(
        `INSERT INTO operations.jobs(queue,job_type,merchant_id,payload)
         VALUES('privacy','customer_erasure',$1,$2)`,
        [merchantId, { requestId: requestRow.id, customerId }],
      );

      await addOutboxEvent(client, {
        eventType: EVENT_TYPES.CUSTOMER_ERASURE_REQUESTED,
        aggregateType: 'customer',
        aggregateId: customerId,
        merchantId,
        correlationId: randomUUID(),
        payload: { requestId: requestRow.id, customerId },
      });

      return { status: 202, body: dto, trigger: true, requestId: requestRow.id };
    });

    if (result.trigger && result.requestId) {
      void this.processSingleErasure(result.requestId, merchantId, customerId).catch(() => {});
    }

    return { status: result.status, body: result.body };
  }

  async get(merchantId: string, requestId: string): Promise<ErasureRequestDto | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    if (!result.rows[0]) return undefined;
    return formatDto(result.rows[0]);
  }

  async processSingleErasure(requestId: string, merchantId: string, customerId: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='processing', attempts=attempts+1, updated_at=now()
       WHERE id=$1 AND merchant_id=$2`,
      [requestId, merchantId],
    );

    try {
      const customerRes = await pool.query<{ email: string; phone: string | null; external_reference: string }>(
        `SELECT email, phone, external_reference FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
        [merchantId, customerId],
      );
      const customer = customerRes.rows[0];
      const customerEmail = customer?.email;

      await transaction(async (client) => {
        // Customer sub-tables
        await client.query(`DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
        await client.query(`DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
        await client.query(`DELETE FROM customers.payment_method_refs WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
        await client.query(`DELETE FROM customers.provider_customer_mappings WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
        await client.query(`DELETE FROM provider_sandbox.customers WHERE merchant_id=$1 AND payflow_customer_id=$2`, [merchantId, customerId]);
        if (customerEmail) {
          await client.query(`DELETE FROM provider_sandbox.customers WHERE merchant_id=$1 AND email=$2`, [merchantId, customerEmail]);
        }

        // Support tickets and messages
        await client.query(`DELETE FROM customers.support_messages WHERE merchant_id=$1 AND author_id=$2`, [merchantId, customerId]);
        await client.query(`DELETE FROM customers.support_participants WHERE customer_id=$1`, [customerId]);
        await client.query(
          `DELETE FROM customers.support_messages WHERE ticket_id IN (
             SELECT t.id FROM customers.support_tickets t
             WHERE t.merchant_id=$1 AND NOT EXISTS(SELECT 1 FROM customers.support_participants p WHERE p.ticket_id=t.id)
           )`,
          [merchantId],
        );
        await client.query(
          `DELETE FROM customers.support_tickets WHERE merchant_id=$1 AND NOT EXISTS(SELECT 1 FROM customers.support_participants p WHERE p.ticket_id=customers.support_tickets.id)`,
          [merchantId],
        );

        // Deliveries, notifications, preferences
        await client.query(`DELETE FROM operations.email_deliveries WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
        if (customerEmail) {
          await client.query(`DELETE FROM operations.email_deliveries WHERE merchant_id=$1 AND destination=$2`, [merchantId, customerEmail]);
        }
        await client.query(`DELETE FROM operations.notifications WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
        if (customerEmail) {
          await client.query(`DELETE FROM operations.notifications WHERE merchant_id=$1 AND destination=$2`, [merchantId, customerEmail]);
        }
        await client.query(`DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
        if (customerEmail) {
          await client.query(`DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND destination=$2`, [merchantId, customerEmail]);
        }

        // Analytics events
        await client.query(`DELETE FROM operations.analytics_events WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
        if (customerEmail) {
          await client.query(`DELETE FROM operations.analytics_events WHERE merchant_id=$1 AND email=$2`, [merchantId, customerEmail]);
        }

        // Audit logs metadata
        await client.query(
          `UPDATE platform.audit_logs SET metadata='{}'::jsonb WHERE merchant_id=$1 AND target_id=$2`,
          [merchantId, customerId],
        );
        if (customerEmail) {
          await client.query(
            `UPDATE platform.audit_logs SET metadata='{}'::jsonb WHERE merchant_id=$1 AND metadata->>'email'=$2`,
            [merchantId, customerEmail],
          );
        }

        // Background jobs and outbox events for this customer
        await client.query(
          `DELETE FROM operations.jobs WHERE merchant_id=$1 AND payload->>'customerId'=$2 AND status IN ('pending','retry','processing') AND queue<>'privacy'`,
          [merchantId, customerId],
        );
        await client.query(
          `DELETE FROM operations.outbox_events WHERE merchant_id=$1 AND aggregate_type='customer' AND aggregate_id=$2 AND status IN ('pending','publishing','retry')`,
          [merchantId, customerId],
        );

        // Anonymize financial records
        await client.query(
          `UPDATE payments.payment_intents
           SET customer_snapshot='{"anonymized": true}'::jsonb, description='Redacted', updated_at=now()
           WHERE merchant_id=$1 AND customer_id=$2`,
          [merchantId, customerId],
        );

        await client.query(
          `UPDATE payments.payment_attempts
           SET request_payload=jsonb_set(request_payload, '{description}', '"Redacted"')
           WHERE merchant_id=$1 AND payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE customer_id=$2)`,
          [merchantId, customerId],
        );

        await client.query(
          `UPDATE payments.refunds SET customer_email=NULL
           WHERE merchant_id=$1 AND payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE customer_id=$2)`,
          [merchantId, customerId],
        );

        await client.query(
          `UPDATE payments.invoices SET billing_snapshot='{"anonymized": true}'::jsonb
           WHERE merchant_id=$1 AND customer_id=$2`,
          [merchantId, customerId],
        );

        // Delete customer record
        await client.query(`DELETE FROM customers.customers WHERE merchant_id=$1 AND id=$2`, [merchantId, customerId]);
      });

      // MinIO cleanup
      await ensureBucket();
      const paymentIds = (await pool.query<{ id: string }>(
        `SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2`,
        [merchantId, customerId],
      )).rows.map((r) => r.id);

      for (const paymentId of paymentIds) {
        const objectKey = `${merchantId}/receipts/${paymentId}.json`;
        try {
          const stream = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
          let data = '';
          for await (const chunk of stream) data += chunk;
          const json = JSON.parse(data) as Record<string, unknown>;
          json.customer = { anonymized: true };
          const newBody = JSON.stringify(json);
          await objectStore.putObject(DOCUMENT_BUCKET, objectKey, newBody, Buffer.byteLength(newBody), { 'Content-Type': 'application/json' });
          const newChecksum = createHash('sha256').update(newBody).digest('hex');
          await pool.query(
            `UPDATE operations.document_manifests SET checksum=$1,metadata=$2 WHERE object_key=$3`,
            [newChecksum, { paymentId, anonymized: true }, objectKey],
          );
        } catch {
          // Object might not exist if receipt was not generated yet
        }
      }

      const invoices = (await pool.query<{ id: string; object_key: string | null }>(
        `SELECT id, object_key FROM payments.invoices WHERE merchant_id=$1 AND customer_id=$2`,
        [merchantId, customerId],
      )).rows;

      for (const inv of invoices) {
        if (!inv.object_key) continue;
        try {
          const stream = await objectStore.getObject(DOCUMENT_BUCKET, inv.object_key);
          let data = '';
          for await (const chunk of stream) data += chunk;
          const json = JSON.parse(data) as Record<string, unknown>;
          json.customer = { anonymized: true };
          const newBody = JSON.stringify(json);
          await objectStore.putObject(DOCUMENT_BUCKET, inv.object_key, newBody, Buffer.byteLength(newBody), { 'Content-Type': 'application/json' });
          const newChecksum = createHash('sha256').update(newBody).digest('hex');
          await pool.query(
            `UPDATE operations.document_manifests SET checksum=$1 WHERE object_key=$2`,
            [newChecksum, inv.object_key],
          );
        } catch {}
      }

      const importManifests = await pool.query<{ object_key: string }>(
        `SELECT object_key FROM operations.document_manifests WHERE merchant_id=$1 AND document_type='customer_import'`,
        [merchantId],
      );
      for (const manifest of importManifests.rows) {
        try {
          const stream = await objectStore.getObject(DOCUMENT_BUCKET, manifest.object_key);
          let data = '';
          for await (const chunk of stream) data += chunk;
          const json = JSON.parse(data) as Record<string, unknown>;
          if (json.customerId === customerId || (customerEmail && json.email === customerEmail)) {
            await objectStore.removeObject(DOCUMENT_BUCKET, manifest.object_key);
            await pool.query(`DELETE FROM operations.document_manifests WHERE object_key=$1`, [manifest.object_key]);
            await pool.query(`DELETE FROM customers.customer_imports WHERE object_key=$1`, [manifest.object_key]);
          }
        } catch {}
      }

      // Redis cleanup
      const redis = this.getRedis();
      await redis.del(`merchant:${merchantId}:customer:${customerId}`);
      await redis.del(`merchant:${merchantId}:customer:${customerId}:activity`);

      // OpenSearch cleanup
      try {
        await searchClient.delete({ index: CUSTOMER_INDEX, id: `${merchantId}:${customerId}`, refresh: true });
      } catch {}

      // Mailpit cleanup
      if (customerEmail) {
        try {
          await deleteMailpitMessagesForRecipient(customerEmail);
        } catch {}
      }

      // Mark completed
      await transaction(async (client) => {
        await client.query(
          `UPDATE customers.erasure_requests
           SET status='completed', completed_at=now(), last_error=NULL, updated_at=now()
           WHERE id=$1 AND merchant_id=$2`,
          [requestId, merchantId],
        );
        await addOutboxEvent(client, {
          eventType: EVENT_TYPES.CUSTOMER_ERASED,
          aggregateType: 'customer',
          aggregateId: customerId,
          merchantId,
          correlationId: randomUUID(),
          payload: { requestId, customerId },
        });
      });
    } catch (error) {
      await pool.query(
        `UPDATE customers.erasure_requests
         SET status='failed', last_error='cleanup_failed', updated_at=now()
         WHERE id=$1 AND merchant_id=$2`,
        [requestId, merchantId],
      );
      throw error;
    }
  }

  async runWorker(signal: AbortSignal): Promise<void> {
    const workerId = `customer-erasure-worker-${randomUUID()}`;
    while (!signal.aborted) {
      try {
        const job = await this.claimErasureJob(workerId);
        if (job) {
          try {
            await this.processSingleErasure(job.requestId, job.merchantId, job.customerId);
            await pool.query(`UPDATE operations.jobs SET status='completed' WHERE id=$1`, [job.jobId]);
          } catch {
            await pool.query(`UPDATE operations.jobs SET status='retry', available_at=now()+interval '5 seconds' WHERE id=$1`, [job.jobId]);
          }
        } else {
          await new Promise((resolve) => setTimeout(resolve, 500));
        }
      } catch {
        await new Promise((resolve) => setTimeout(resolve, 1000));
      }
    }
    if (this.redis) {
      await this.redis.quit();
      this.redis = null;
    }
  }

  private async claimErasureJob(workerId: string): Promise<{ jobId: string; requestId: string; merchantId: string; customerId: string } | undefined> {
    return await transaction(async (client) => {
      const result = await client.query<{ id: string; merchant_id: string; payload: { requestId: string; customerId: string } }>(
        `UPDATE operations.jobs
         SET status='processing', attempts=attempts+1, locked_by=$1, locked_at=now(),
             lease_expires_at=now()+interval '60 seconds'
         WHERE id=(SELECT id FROM operations.jobs
           WHERE queue='privacy' AND status IN ('pending','retry') AND available_at<=now()
           ORDER BY available_at,created_at FOR UPDATE SKIP LOCKED LIMIT 1)
         RETURNING id, merchant_id, payload`,
        [workerId],
      );
      const row = result.rows[0];
      if (!row) return undefined;
      return {
        jobId: row.id,
        requestId: row.payload.requestId,
        merchantId: row.merchant_id,
        customerId: row.payload.customerId,
      };
    });
  }
}
