import test from 'node:test';
import { randomUUID, createHash } from 'node:crypto';
import { EVENT_TYPES, eventEnvelopeSchema } from '../packages/contracts/src/events.js';
import { requestHash } from '../apps/payment-service/src/idempotency.js';

test('privacy event types are defined in contracts', () => {
  assert.equal(EVENT_TYPES.CUSTOMER_ERASURE_REQUESTED, 'customer.erasure.requested.v1');
  assert.equal(EVENT_TYPES.CUSTOMER_ERASED, 'customer.erased.v1');

  const envelope = eventEnvelopeSchema.parse({
    eventId: randomUUID(),
    eventType: EVENT_TYPES.CUSTOMER_ERASED,
    eventVersion: 1,
    occurredAt: new Date().toISOString(),
    aggregateType: 'customer',
    aggregateId: randomUUID(),
    merchantId: randomUUID(),
    correlationId: randomUUID(),
    payload: { customerId: randomUUID() },
  });
  assert.equal(envelope.eventType, 'customer.erased.v1');
});

test('idempotency hashing for erasure requests differentiates customer targets', () => {
  const customerA = randomUUID();
  const customerB = randomUUID();
  const hashA = requestHash({ customerId: customerA });
  const hashB = requestHash({ customerId: customerB });

  assert.equal(hashA, createHash('sha256').update(JSON.stringify({ customerId: customerA })).digest('hex'));
  assert.notEqual(hashA, hashB);
});

test('idempotency key length validation rules', () => {
  function isValidIdempotencyKey(key: unknown): boolean {
    return typeof key === 'string' && key.length >= 8 && key.length <= 200;
  }

  assert.equal(isValidIdempotencyKey('short'), false);
  assert.equal(isValidIdempotencyKey(''), false);
  assert.equal(isValidIdempotencyKey(null), false);
  assert.equal(isValidIdempotencyKey('12345678'), true);
  assert.equal(isValidIdempotencyKey('a'.repeat(200)), true);
  assert.equal(isValidIdempotencyKey('a'.repeat(201)), false);
});
"}

