import { config } from '../packages/config/src/index.js';
import { pool } from '../packages/database/src/pool.js';
import { CUSTOMER_INDEX, searchClient } from '../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../packages/storage/src/minio.js';

const gateway = process.env.GATEWAY_URL ?? 'http://localhost:3000';
const apiKey = process.env.PAYFLOW_API_KEY ?? 'pf_local_dev_northstar_4ad1539de977';
const secondApiKey = 'pf_local_dev_bluebird_924bd90d2201';

interface ApiResponse<T> {
  status: number;
  body: T;
}

async function api<T>(
  path: string,
  method = 'GET',
  body?: unknown,
  headers: Record<string, string> = {},
  key = apiKey,
): Promise<ApiResponse<T>> {
  const reqHeaders: Record<string, string> = {
    authorization: `Bearer ${key}`,
    ...headers,
  };
  const init: RequestInit = { method, headers: reqHeaders };
  if (body !== undefined) {
    reqHeaders['content-type'] = 'application/json';
    init.body = JSON.stringify(body);
  }
  const response = await fetch(`${gateway}${path}`, init);
  let resBody: T;
  try {
    resBody = await response.json() as T;
  } catch {
    resBody = {} as T;
  }
  return { status: response.status, body: resBody };
}

test('Customer Data Deletion full lifecycle and retention guarantees', async () => {
  const suffix = randomUUID();
  const customerEmail = `privacy-test-${suffix}@example.test`;

  // 1. Create a customer
  const createCustomerRes = await api<{ id: string }>(
    '/v1/customers',
    'POST',
    {
      externalReference: `privacy-ext-${suffix}`,
      email: customerEmail,
      name: `Privacy Subject ${suffix}`,
      phone: '+1-555-0199',
      metadata: { department: 'privacy-testing' },
    },
  );
  assert.equal(createCustomerRes.status, 201);
  const customerId = createCustomerRes.body.id;

  // Add address
  await api(`/v1/customers/${customerId}/addresses`, 'POST', {
    kind: 'billing',
    line1: '123 Privacy Lane',
    city: 'San Francisco',
    postalCode: '94105',
    country: 'US',
  });

  // Add contact
  await api(`/v1/customers/${customerId}/contacts`, 'POST', {
    kind: 'email',
    value: customerEmail,
    isPrimary: true,
  });

  // Add payment method
  const pmRes = await api<{ id: string }>(`/v1/customers/${customerId}/payment-methods`, 'POST', {
    providerToken: `tok_live_${suffix}`,
    type: 'card',
    brand: 'visa',
    last4: '4242',
    billingName: `Privacy Subject ${suffix}`,
  });
  assert.equal(pmRes.status, 201);
  const paymentMethodId = pmRes.body.id;

  // Add support ticket
  await api(`/v1/customers/${customerId}/support-tickets`, 'POST', {
    subject: 'Privacy Inquiry',
    body: `Please handle my personal data at ${customerEmail}.`,
  });

  // Add customer import
  await api('/v1/customer-imports', 'POST', {
    source: 'test-crm',
    record: { customerId, email: customerEmail, name: `Privacy Subject ${suffix}` },
  });

  // Add invoice
  const invRes = await api<{ id: string }>(
    '/v1/invoices',
    'POST',
    {
      customerId,
      currency: 'USD',
      tax: 100,
      lines: [{ description: 'Test Subscription', quantity: 1, unitAmount: 1000 }],
    },
  );
  assert.equal(invRes.status, 200);
  const invoiceId = invRes.body.id;

  // Process a payment
  const payRes = await api<{ id: string }>(
    '/v1/payments',
    'POST',
    {
      customerId,
      paymentMethodId,
      amount: 1100,
      currency: 'USD',
      description: `Test payment for ${customerEmail}`,
    },
    { 'idempotency-key': `pay-${suffix}` },
  );
  assert.equal(payRes.status, 202);
  const paymentId = payRes.body.id;

  // Wait 2s for async workers to project to OpenSearch, Redis, MinIO, Mailpit
  await new Promise((resolve) => setTimeout(resolve, 2500));

